<?php declare(strict_types=1); require __DIR__ . '/admin.php'; requireAdmin($database); if ($_SERVER['REQUEST_METHOD'] === 'POST') { $database->prepare('UPDATE orders SET status = :status WHERE id = :id')->execute(['status' => (string) $_POST['status'], 'id' => (int) $_POST['id']]); } $orders = $database->query('SELECT id, user_id, status, total_amount, created_at FROM orders ORDER BY created_at DESC')->fetchAll(); adminHeader('Manage orders'); ?><h1>Manage orders</h1><table><tr><th>ID</th><th>User</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach ($orders as $order): ?><tr><td><?= (int) $order['id'] ?></td><td><?= (int) $order['user_id'] ?></td><td>₹<?= number_format((float) $order['total_amount'], 2) ?></td><td><?= htmlspecialchars($order['status'], ENT_QUOTES, 'UTF-8') ?></td><td><form method="post"><input type="hidden" name="id" value="<?= (int) $order['id'] ?>"><select name="status"><option>pending</option><option>confirmed</option><option>shipped</option><option>delivered</option><option>cancelled</option></select><button>Update</button></form></td></tr><?php endforeach; ?></table><?php adminFooter(); ?>
